#!/usr/bin/env bash
# Extract the mediawiki Freeciv manual generated by the pinned game image.
set -euo pipefail
cd "$(dirname "$0")/.."

CONTAINER="${FREECIV_CONTAINER:-freeciv-web}"
IMAGE_REF="${FREECIV_IMAGE_REF:-civrealm/freeciv-web@sha256:4923253876a76d3c5f55c6007e530f6c3cd3120b9e2f37a8e943faf920cb373a}"
OUTPUT_DIR="${FREECIV_MANUAL_DIR:-artifacts/reference/freeciv-manual}"
REQUIRED="${FREECIV_MANUAL_REQUIRED:-0}"
RULESET="classic"

fail_or_warn() {
  if [ "$REQUIRED" = 1 ]; then
    echo "freeciv manual extraction failed: $1" >&2
    exit 1
  fi
  echo "warning: freeciv manual unavailable: $1" >&2
  exit 0
}

docker_cmd() {
  if docker info >/dev/null 2>&1; then docker "$@"
  elif command -v sg >/dev/null 2>&1; then sg docker -c "$(printf '%q ' docker "$@")"
  else return 125
  fi
}

json_escape() { printf '%s' "$1" | sed 's/\\/\\\\/g; s/"/\\"/g'; }
manifest_value() { sed -n "s/.*\"$1\": \"\([^\"]*\)\".*/\1/p" "$2" | head -n 1; }

command -v docker >/dev/null 2>&1 || fail_or_warn "Docker CLI is not installed"
docker_cmd info >/dev/null 2>&1 || fail_or_warn "Docker API is unavailable (check the daemon/socket permissions)"
docker_cmd inspect "$CONTAINER" >/dev/null 2>&1 || fail_or_warn "container '$CONTAINER' is unavailable"
expected_image_id="$(docker_cmd image inspect -f '{{.Id}}' "$IMAGE_REF" 2>/dev/null || true)"
actual_image_id="$(docker_cmd inspect -f '{{.Image}}' "$CONTAINER" 2>/dev/null || true)"
[ -n "$expected_image_id" ] || fail_or_warn "pinned image '$IMAGE_REF' is not available locally"
[ "$actual_image_id" = "$expected_image_id" ] || fail_or_warn "container '$CONTAINER' does not use pinned image '$IMAGE_REF'"
image_version="$(docker_cmd image inspect -f '{{index .Config.Labels "org.opencontainers.image.version"}}' "$IMAGE_REF" 2>/dev/null || true)"
[ -n "$image_version" ] || image_version="unknown (pinned image digest)"

manual_bin="$(docker_cmd exec --user docker "$CONTAINER" sh -c '
  for p in /home/docker/freeciv/bin/freeciv-manual /usr/local/bin/freeciv-manual /usr/bin/freeciv-manual; do
    [ -x "$p" ] && { printf "%s\n" "$p"; exit 0; }
  done
  exit 1
' 2>/dev/null || true)"
[ -n "$manual_bin" ] || fail_or_warn "freeciv-manual was not found in supported Freeciv prefixes"
# The path is selected from this fixed allow-list before it is passed as a
# positional parameter to the container shell; never interpolate container
# output into shell source.
case "$manual_bin" in
  /home/docker/freeciv/bin/freeciv-manual|/usr/local/bin/freeciv-manual|/usr/bin/freeciv-manual) ;;
  *) fail_or_warn "freeciv-manual returned an unsafe path" ;;
esac
manual_version="$(docker_cmd exec --user docker "$CONTAINER" "$manual_bin" --version 2>/dev/null | head -n 1 || true)"
[ -n "$manual_version" ] || manual_version="unknown"

parent_dir="$(dirname "$OUTPUT_DIR")"
mkdir -p "$parent_dir"
files=()
for n in 1 2 3 4 5 6 7 8; do files+=("classic$n.mediawiki"); done

if [ -e "$OUTPUT_DIR" ]; then
  manifest="$OUTPUT_DIR/reference.json"
  if [ -f "$manifest" ] && [ "$(manifest_value schema_version "$manifest")" = "freeciv-manual-reference-v1" ] \
      && [ "$(manifest_value image_ref "$manifest")" = "$IMAGE_REF" ] \
      && [ "$(manifest_value ruleset "$manifest")" = "$RULESET" ]; then
    valid=1
    for file in "${files[@]}"; do
      [ -f "$OUTPUT_DIR/$file" ] || valid=0
      expected="$(sed -n "s/.*\"$file\": \"\([^\"]*\)\".*/\1/p" "$manifest" | head -n 1)"
      actual="$(sha256sum "$OUTPUT_DIR/$file" 2>/dev/null | awk '{print $1}')"
      [ -n "$expected" ] && [ "$expected" = "$actual" ] || valid=0
    done
    if [ "$valid" = 1 ]; then
      echo "freeciv manual verified at $OUTPUT_DIR; leaving it untouched"
      exit 0
    fi
  fi
  fail_or_warn "existing manual at $OUTPUT_DIR failed provenance or checksum verification; remove/repair it before retrying"
fi

staging="$(mktemp -d "$parent_dir/.freeciv-manual.XXXXXX")"
container_dir=""
cleanup() {
  rm -rf -- "$staging"
  case "$container_dir" in
    /tmp/lechonk-freeciv-manual.[A-Za-z0-9]*)
      docker_cmd exec --user docker "$CONTAINER" rm -rf -- "$container_dir" >/dev/null 2>&1 || true ;;
  esac
}
trap cleanup EXIT

container_dir="$(docker_cmd exec --user docker "$CONTAINER" sh -c '
  set -eu
  d=$(mktemp -d /tmp/lechonk-freeciv-manual.XXXXXX)
  cd "$d"
  "$1" --ruleset classic --wiki >generation.log 2>&1
  for n in 1 2 3 4 5 6 7 8; do test -s "classic$n.mediawiki"; done
  printf "%s\n" "$d"
' sh "$manual_bin" 2>/dev/null | tail -n 1)" || fail_or_warn "manual generation failed in container '$CONTAINER'"
case "$container_dir" in /tmp/lechonk-freeciv-manual.[A-Za-z0-9]*) ;; *) fail_or_warn "container returned an unsafe temporary path" ;; esac
docker_cmd cp "$CONTAINER:$container_dir/." "$staging/" || fail_or_warn "could not copy generated manual from container '$CONTAINER'"

for file in "${files[@]}"; do
  [ -f "$staging/$file" ] || fail_or_warn "generated manual is missing $file"
done
find "$staging" -mindepth 1 -maxdepth 1 -type f ! -name 'classic*.mediawiki' -delete

safe_ref="$(json_escape "$IMAGE_REF")"; safe_version="$(json_escape "$image_version")"
safe_manual="$(json_escape "$manual_bin")"; safe_mv="$(json_escape "$manual_version")"
{
  echo '{'
  echo '  "schema_version": "freeciv-manual-reference-v1",'
  echo "  \"image_ref\": \"$safe_ref\","
  echo "  \"image_id\": \"$(json_escape "$expected_image_id")\","
  echo "  \"image_version\": \"$safe_version\","
  echo "  \"container\": \"$(json_escape "$CONTAINER")\","
  echo "  \"ruleset\": \"$RULESET\","
  echo "  \"manual_binary\": \"$safe_manual\","
  echo "  \"manual_version\": \"$safe_mv\","
  echo '  "format": "mediawiki",'
  echo '  "files": {'
  for i in "${!files[@]}"; do
    comma=','; [ "$i" = 7 ] && comma=''
    file="${files[$i]}"
    echo "    \"$file\": \"$(sha256sum "$staging/$file" | awk '{print $1}')\"$comma"
  done
  echo '  },'
  echo '  "license": "Freeciv data is GPL-2.0-or-later; retain upstream notices before redistribution."'
  echo '}'
} > "$staging/reference.json"
cat > "$staging/LICENSE.txt" <<'EOF'
This directory contains mediawiki manuals generated from Freeciv's classic
ruleset by the pinned image recorded in reference.json. Freeciv data is
GPL-2.0-or-later; retain upstream notices before redistribution.
EOF
mv "$staging" "$OUTPUT_DIR" || fail_or_warn "destination appeared during extraction; no files were replaced"
trap - EXIT
cleanup
echo "extracted Freeciv manual to $OUTPUT_DIR (classic ruleset; 8 mediawiki files)"
